from research_helpers import *
S=ev('https://www.krakenrobotics.com/wp-content/uploads/2025/05/SAS_Kraken_Flyer_Letter.pdf','Official model table names MP-SAS, SAS-60 and SAS-120; array lengths/depth configurations not multiplied into unsupported SKUs.')
K=ev('https://www.krakenrobotics.com/products/katfish/','Current actively stabilized sonar towfish plus separate ISO20 and USV autonomous launch/recovery systems.')
B=ev('https://www.krakenrobotics.com/products/seapower/','Current subsea lithium-ion battery family, pressure-tolerant polymer encapsulation and integrated BMS; not a claim of every possible custom configuration.')
BH=ev('https://www.krakenrobotics.com/wp-content/uploads/2025/05/SeaPower_Kraken_Flyer_A4.pdf','Official battery flyer specifies 6000 m pressure tolerance; battery capacity scalable rather than named SKU inventory.')
H=ev('https://www.krakenrobotics.com/news-releases/kraken-takes-delivery-of-thunderfish-auv/','ThunderFish Alpha formerly DEDAVE acquired from Fraunhofer; recorded owner, not original developer. Also names DataPod storage and SeaVision.')
X=ev('https://www.krakenrobotics.com/news-releases/kraken-announces-3-5-million-of-contract-funding-awards/','Historical ThunderFish XL and SeaVision development; no assumption of current commercialization.')
M=ev('https://www.krakenrobotics.com/news-releases/kraken-announces-aquapix-minsas-240-sensor/','Issuer introduces MINSAS-240 with 240 cm modular array; not silently equated to current SAS-120.')
SW=ev('https://www.krakenrobotics.com/wp-content/uploads/2020/12/Kraken-MDA-Q2-2019-FINAL.3.pdf','Historical issuer names RTSAS MK-II processing hardware and SASView software. Earlier MINSAS 60/120 rename mapping unresolved; not duplicated against current names.')
A=ev('https://www.krakenrobotics.com/news-releases/kraken-robotics-announces-closing-of-strategic-acquisition-of-covelya-group-limited-updated-2026-guidance-and-appointments-to-executive-team/','July 2 2026 completed Covelya acquisition; acquired product catalogues require separate portfolio review.')
kp=[p(n,'Synthetic aperture sonar payload for underwater vehicles.',S,'commercial',typ='product',sector='robotics',sub='sensing',attributes={'maximum_sonar_range_per_side_m':r}) for n,r in [('Kraken MP-SAS',100),('Kraken SAS-60',100),('Kraken SAS-120',200)]]
kp += [p('KATFISH','Actively stabilized towed sonar survey system.',K,'commercial',typ='product',sector='robotics',sub='marine_robotics',attributes={'standard_speed_knots':[4,10],'depth_rating_m':300}),p('ISO20 LARS','Autonomous launch and recovery system for KATFISH.',K,'commercial',typ='product',sector='robotics',sub='marine_robotics'),p('USV LARS','Compact autonomous KATFISH launch and recovery system for uncrewed surface vessels.',K,'commercial',typ='product',sector='robotics',sub='marine_robotics'),p('SeaPower','Pressure-tolerant subsea lithium-ion battery system.',B,'commercial',typ='product',sector='energy_storage',sub='batteries',evidence=[B,BH],attributes={'chemistry':'Lithium-ion','depth_rating_m':6000}),p('ThunderFish Alpha','Acquired autonomous underwater technology demonstrator.',H,roles=['owner'],aliases=['DEDAVE'],typ='product',sector='robotics',sub='marine_robotics'),p('ThunderFish XL','Historical subsea-resident hovering autonomous underwater vehicle program.',X,sector='robotics',sub='marine_robotics'),p('SeaVision','Historical subsea three-dimensional laser imaging system.',X,typ='product',sector='robotics',sub='sensing'),p('AquaPix MINSAS-240','Synthetic aperture sonar system for high-speed underwater surveys.',M,typ='product',sector='robotics',sub='sensing'),p('RTSAS MK-II','Historical real-time synthetic aperture sonar processor.',SW,typ='product',sector='robotics',sub='robotics_software'),p('SASView','Historical three-dimensional sonar visualization and control software.',SW,typ='product',sector='robotics',sub='robotics_software')]
N=ev('https://www.insujet.com/collections/insujet-needle-free-insulin-delivery-system','Current issuer-linked store lists V5 injector, nozzle and adaptor; starter pack is packaging bundle, not additional underlying product.')
NH=ev('https://insujet.com/en-ph/pages/insujet-how-it-works','Official instructions distinguish 3 mL and 10 mL adaptors, nozzle and comfort ring.')
NC=ev('https://www.nugenmd.com/products/','Official issuer describes development and commercialization of spring-powered drug-delivery technology and links InsuJet brand.')
ND=ev('https://www.nugenmd.com/news/2025/nugen-medical-devices-announces-new-needle-free-injection-system-featuring-internal-cartridge-technology/','Issuer describes unnamed future internal-cartridge system. Not fabricated as branded commercial product; additional research follow-up needed.')
np=[p(n,d,N,'commercial',typ='product',sub='drug_delivery',evidence=[N,NH,NC]) for n,d in [('InsuJet Injector V5','Needle-free insulin injection device.'),('InsuJet Nozzle','Replaceable insulin reservoir nozzle for InsuJet.'),('InsuJet Adaptor 3 mL','Adaptor connecting 3 mL insulin cartridges or pens to an InsuJet nozzle.'),('InsuJet Adaptor 10 mL','Adaptor connecting 10 mL insulin containers to an InsuJet nozzle.'),('InsuJet Comfort Ring','Comfort accessory for needle-free insulin administration.')]]
companies=[company('Kraken Robotics Inc',kp,[S,K,B,BH,H,X,M,SW,A],'Current core sonar, towfish, launch/recovery and battery products plus historical named assets reviewed. Covelya/3D at Depth acquired catalogues, legacy sonar renames, DataPod versions and thruster models require further review.'),company('NuGen Medical Devices Inc',np,[N,NH,NC,ND],'Current V5 injector and distinct functional consumables reviewed; packaging bundles excluded. Earlier device generations and unnamed internal-cartridge development system require identity and latest-status reconciliation.')]
(out/'batch-0014.json').write_text(json.dumps({'companies':companies},indent=2))
